mapper.select:
select distinct tt.* from ( select portfolioId,portfolioName,secAcctId,secAcctName,finprodId,finprodMarketId,finprodAbbr, type9, type10, type11, type12, type8, type7, type6, case when type8= #{finprodType2_F01} then (PTL_AMOUNT03 + PTL_AMOUNT05 - PTL_AMOUNT06)*100 else (PTL_AMOUNT03 + PTL_AMOUNT05 - PTL_AMOUNT06) end as actualPositionAmount,
case when type8= #{finprodType2_F01} then (PTL_FLOW_AMOUNT01 + PTL_AMOUNT03 + PTL_AMOUNT05 - PTL_AMOUNT06 - PTL_AMOUNT04 + PTL_AMOUNT08 + andOneDataAmout)*100
else (PTL_FLOW_AMOUNT01 + PTL_AMOUNT03 + PTL_AMOUNT05 - PTL_AMOUNT06 - PTL_AMOUNT04 + PTL_AMOUNT08) end as tradePositionAmount, case when type8= #{finprodType2_F01} then ETR_FLOW_AMOUNTE01*100 else ETR_FLOW_AMOUNTE01 end as instructionsAmount, case when type8= #{finprodType2_F01} then ETR_FLOW_AMOUNT04*100 else ETR_FLOW_AMOUNT04 end as pledgeAmount, case when type8= #{finprodType2_F01} then (PTL_AMOUNT04)*100 else (PTL_AMOUNT04) end as preReductionAmount from ( select t.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, nvl(nvl(chl.FINPROD_MARKET_ID, chl1.FINPROD_MARKET_ID), t.SEC_ACCT_ID) secAcctId, nvl(t4.SEC_ACCT_NAME, nvl(chl.FINPROD_ABBR, chl1.FINPROD_ABBR)) secAcctName, t.FINPROD_ID finprodId, nvl(fp.FINPROD_MARKET_ID, t.FINPROD_ID) finprodMarketId, nvl(fp.FINPROD_ABBR, t.FINPROD_ID) finprodAbbr, t5.TYPE_9 type9, t5.TYPE_10 type10, t5.TYPE_11 type11, t5.TYPE_12 type12, t5.TYPE_8 type8, t5.TYPE_7 type7, t5.TYPE_6 type6, nvl(sum(PTL_AMOUNT03),0) as PTL_AMOUNT03, nvl(sum(PTL_AMOUNT04),0) as PTL_AMOUNT04, nvl(sum(PTL_AMOUNT05),0) as PTL_AMOUNT05, nvl(sum(PTL_AMOUNT06),0) as PTL_AMOUNT06, nvl(sum(PTL_AMOUNT08),0) as PTL_AMOUNT08, nvl(sum(PTL_FLOW_AMOUNT01),0) as PTL_FLOW_AMOUNT01, nvl(sum(ETR_FLOW_AMOUNTE01),0) as ETR_FLOW_AMOUNTE01, nvl(sum(ETR_FLOW_AMOUNT04),0) as ETR_FLOW_AMOUNT04
, nvl(sum(andOneDataAmout),0) as andOneDataAmout
from ( SELECT t6.portfolio_id, DECODE(t6.sec_acct_id, '999999', NULL, t6.sec_acct_id) sec_acct_id, t6.finprod_id, t6.PTL_AMOUNT03, t6.PTL_AMOUNT04, t6.PTL_AMOUNT05, t6.PTL_AMOUNT06, t6.PTL_AMOUNT08, t7.PTL_FLOW_AMOUNT01, t8.ETR_FLOW_AMOUNTE01, t8.ETR_FLOW_AMOUNT04
, t_andOneData.andOneDataAmout
FROM ( select portfolio_id, sec_acct_id, finprod_id, nvl(sum(case when hoding_type = '03' then AMOUNT end),0) PTL_AMOUNT03, nvl(sum(case when hoding_type = '04' then AMOUNT end),0) PTL_AMOUNT04, nvl(sum(case when hoding_type = '05' then AMOUNT end),0) PTL_AMOUNT05, nvl(sum(case when hoding_type = '06' then AMOUNT end),0) PTL_AMOUNT06, nvl(sum(case when hoding_type = '08' then AMOUNT end),0) PTL_AMOUNT08 from PTL_SEC_POSITION where portfolio_id = #{portfolioId,jdbcType=VARCHAR} and cdate = to_date(#{cdate},'yyyy-MM-dd')
and finprod_id = #{finprodId,jdbcType=VARCHAR}
#{secHodingType,jdbcType=VARCHAR}
group by portfolio_id, sec_acct_id, finprod_id ) t6 left join ( select portfolio_id, finprod_id,sec_acct_id, nvl(sum(case when hoding_type = '01' then AMOUNT end),0) PTL_FLOW_AMOUNT01 from PTL_SEC_POSITION_FLOW where portfolio_id = #{portfolioId,jdbcType=VARCHAR}
and finprod_id = #{finprodId,jdbcType=VARCHAR}
and cdate <= to_date(#{cdate},'yyyy-MM-dd')
#{secFlowHodingType,jdbcType=VARCHAR}
group by portfolio_id,finprod_id,sec_acct_id ) t7 on t7.portfolio_id = t6.portfolio_id and t7.finprod_id = t6.finprod_id and t7.sec_acct_id=t6.sec_acct_id left join ( select A.portfolio_id, A.finprod_id, A.sec_acct_id, nvl(sum(case when A.hoding_type = 'E01' then A.AMOUNT end),0) ETR_FLOW_AMOUNTE01, nvl(sum(case when A.hoding_type = '04' then A.AMOUNT end),0) ETR_FLOW_AMOUNT04 from ( select A.portfolio_id, A.sec_acct_id, A.finprod_id, A.AMOUNT, A.hoding_type from ETR_SEC_POSITION A where A.portfolio_id = #{portfolioId,jdbcType=VARCHAR} and A.cdate = to_date(#{cdate},'yyyy-MM-dd')
and finprod_id = #{finprodId,jdbcType=VARCHAR}
#{etrFlowHodingType,jdbcType=VARCHAR}
)A group by A.portfolio_id, A.finprod_id, A.sec_acct_id ) t8 on t8.portfolio_id = t6.portfolio_id and t8.finprod_id = t6.finprod_id and t8.sec_acct_id = t6.sec_acct_id
left join ( select portfolio_id, finprod_id,sec_acct_id, sum(AMOUNT) andOneDataAmout from PTL_SEC_POSITION_FLOW where portfolio_id = #{portfolioId,jdbcType=VARCHAR}
and finprod_id = #{finprodId,jdbcType=VARCHAR}
and cdate > to_date(#{cdate},'yyyy-MM-dd') AND AMOUNT < 0 AND HODING_TYPE = '03' AND TRADE_ID IN ( SELECT TOTLE_TRADE_ID FROM TRD_FIN_PRODUCT_DEAL_TOTAL WHERE FINPROD_TYPE2 = 'F01' AND TRADE_DATE <= to_date(#{cdate},'yyyy-MM-dd') AND SETTLE_DATE > to_date(#{cdate},'yyyy-MM-dd') AND TRADE_STATUS = '01' AND (IS_CANCEL = 'N' OR IS_CANCEL IS NULL) ) group by portfolio_id,finprod_id,sec_acct_id ) t_andOneData on t_andOneData.portfolio_id = t6.portfolio_id and t_andOneData.finprod_id = t6.finprod_id and t_andOneData.sec_acct_id = t6.sec_acct_id
) t left join PTL_PORTFOLIO pp on t.PORTFOLIO_ID = pp.PORTFOLIO_ID left join STL_SEC_ACCT_INFO t4 on t4.sec_acct_id = t.sec_acct_id left join FIN_PRODUCT chl on t.SEC_ACCT_ID = chl.FINPROD_ID left join FIN_PRODUCT fp on t.FINPROD_ID = fp.FINPROD_ID left JOIN fin_product_type t5 on t5.finprod_id = t.finprod_id left join (select distinct FINPROD_ID, CHL_FINPROD_ID from FIN_CASH_INFO fci where CHL_FINPROD_ID is not null
and fci.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
) fci on fci.FINPROD_ID = t.FINPROD_ID left join fin_product chl1 on fci.CHL_FINPROD_ID = chl1.FINPROD_ID
and t5.type_8 = #{type8,jdbcType=VARCHAR}
and t5.type_9 = #{type9,jdbcType=VARCHAR}
and t5.type_10 = #{type10,jdbcType=VARCHAR}
and t5.type_11 = #{type11,jdbcType=VARCHAR}
and t5.type_12 = #{type12,jdbcType=VARCHAR}
and t.SEC_ACCT_ID = #{secManageAcctId,jdbcType=VARCHAR}
group by t.PORTFOLIO_ID, pp.PORTFOLIO_NAME, NVL(NVL(chl.FINPROD_MARKET_ID, chl1.FINPROD_MARKET_ID), t.SEC_ACCT_ID ), t4.SEC_ACCT_NAME, chl.FINPROD_ABBR, chl1.FINPROD_ABBR, t.FINPROD_ID, fp.FINPROD_MARKET_ID, fp.FINPROD_ABBR, t5.TYPE_9, t5.TYPE_10, t5.TYPE_11, t5.TYPE_12, t5.TYPE_8, t5.TYPE_7, T5.TYPE_6 ) mm ) tt where ( actualPositionAmount <> 0 or tradePositionAmount <> 0 or instructionsAmount <> 0 or pledgeAmount <> 0 or preReductionAmount <> 0 ) order by portfolioId desc,type8 desc,secAcctId desc,finprodMarketId desc

SELECT
t.finprod_id object,
t.finprod_market_id id,
NVL(t.finprod_abbr,t.finprod_market_id) text
FROM
FIN_PRODUCT t
INNER JOIN fin_product_type t1 on t1.finprod_id = t.finprod_id
WHERE
1=1

    and t1.type_8 = #{type8,jdbcType = VARCHAR}


    and t1.type_9 = #{type9,jdbcType=VARCHAR}


    and t1.type_10 = #{type10,jdbcType=VARCHAR}


    and t1.type_11 = #{type11,jdbcType=VARCHAR}


    and t1.type_12 = #{type12,jdbcType=VARCHAR}


    AND (t.finprod_market_id LIKE CONCAT('%',CONCAT(#{search},'%'))
    OR t.finprod_abbr LIKE CONCAT('%',CONCAT(#{search},'%')))



        #{noshowType8,jdbcType=VARCHAR}

select portfolio_id, sec_acct_id ,finprod_id,actualPositionAmount from ( select portfolio_id, sec_acct_id ,finprod_id,actualPositionAmount from ( select portfolio_id, sec_acct_id, finprod_id, nvl(sum(case when hoding_type = '03' then AMOUNT end), 0)+ nvl(sum(case when hoding_type = '05' then AMOUNT end), 0) - nvl(sum(case when hoding_type = '06' then AMOUNT end), 0) actualPositionAmount from PTL_SEC_POSITION where portfolio_id = #{portfolioId,jdbcType=VARCHAR} and cdate = to_date(#{cdate},'yyyy-MM-dd')
and finprod_id = #{finprodId,jdbcType=VARCHAR}
#{secHodingType,jdbcType=VARCHAR}
group by portfolio_id, sec_acct_id, finprod_id ) t
order by actualPositionAmount desc ) where rownum=1

SELECT NVL(SUM(CASE WHEN A.hoding_type = 'E01' THEN A.AMOUNT END),0) ETR_FLOW_AMOUNTE01 FROM ( SELECT A.portfolio_id, A.sec_acct_id, A.finprod_id, A.AMOUNT, A.hoding_type FROM ETR_SEC_POSITION A WHERE A.portfolio_id = #{portfolioId,jdbcType=VARCHAR} AND A.cdate = to_date(#{cdate},'yyyy-MM-dd')
AND A.finprod_id = #{finprodId,jdbcType=VARCHAR}
#{etrFlowHodingType,jdbcType=VARCHAR}
)A

        SELECT 
			 NVL(SUM(CASE WHEN hoding_type = '03' THEN AMOUNT end),0)+
			 NVL(SUM(CASE WHEN hoding_type = '05' THEN AMOUNT end),0) -
			 NVL(SUM(CASE WHEN hoding_type = '06' THEN AMOUNT end),0)  actualPositionAmount
		FROM PTL_SEC_POSITION
        WHERE portfolio_id = #{portfolioId,jdbcType=VARCHAR} 
	        AND CDATE = to_date(#{cdate},'yyyy-MM-dd')

				and finprod_id = #{finprodId,jdbcType=VARCHAR}



					#{secHodingType,jdbcType=VARCHAR}
